// Get the input JSON
const input = $input.first().json.query;

// Helper function: replace '+' with spaces and convert to lowercase
const cleanText = (value) => value.replace(/\+/g, " ").trim().toLowerCase();

// Extract location (City + Country)
let city = "";

if (Array.isArray(input.locations) && input.locations.length > 0) {
	const parts = input.locations[0].split("+");
	city = (parts[0] || "").trim().toLowerCase();
}

// Convert business keywords
let keywords = [];

if (Array.isArray(input.businesses) && input.businesses.length > 0) {
	keywords = input.businesses.map(cleanText);
}

// Convert job titles
let jobTitles = [];

if (Array.isArray(input.job_titles) && input.job_titles.length > 0) {
	jobTitles = input.job_titles.map(cleanText);
}

// Return transformed JSON
return [
	{
		json: {
			contact_email_exclude_catch_all_domains: false,
			contact_job_titles: jobTitles,
			contact_location: city ? [city] : [],
			email_status: ["verified"],
			keywords: keywords,
			max_result: 25
		}
	}
];
